+            let x_hi = xs[0].max(xs[1]) + (o0.0 + rad[0]).max(o1.0 + rad[1]);
+            let y_lo = ys[0].min(ys[1]) + (o0.1 - rad[0]).min(o1.1 - rad[1]);
+            let y_hi = ys[0].max(ys[1]) + (o0.1 + rad[0]).max(o1.1 + rad[1]);
+            out.push(Cell {
+                t0: Point2::new(p.x, p.y),
+                d,
+                o: [o0, o1],
+                r: rad,
+                z0: p.z + b,
+                z1: q.z + b,
+                flanks,
+                lo: Point2::new(p.x + x_lo, p.y + y_lo),
