+                over = Some(over.map_or((a, b), |(lo, hi): (f64, f64)| (lo.min(a), hi.max(b))));
+            }
+        };
+        for k in 0..2 {
+            join(span((p.0 - self.o[k].0, p.1 - self.o[k].1), back, self.r[k] * self.r[k]));
+        }
+        if let Some(planes) = &self.flanks {
