+                let after = (k1 < hi).then(|| z(k1).min(z(hi)));
+                match (before, after) {
+                    (Some(a), Some(b)) => Some(a.min(b)),
+                    (a, b) => a.or(b),
+                }
+            }
+        }
+    }
